data = {"version":"m4y-subject-findings-v1","method":"Original, qualified subject readings from D1 ownership/house themes; sign capacity follows the supplied board; no verified-event claims.","lord_houses":{},"occupant_themes":{}}
for category, block in rows.items():
    entries = []
    for line in block.strip().splitlines():
        house, hi, en = line.split('|')
        entries.append({"house":int(house),"text":{"hi":hi,"en":en}})
    if [row['house'] for row in entries] != list(range(1,13)):
        raise ValueError(f'Incomplete house coverage: {category}')
    data['lord_houses'][category] = entries
for category, entries in themes.items():
    data['occupant_themes'][category] = {planet:{"hi":hi,"en":en} for planet,hi,en in entries}
Path('internal/platform/data/faladesh-findings.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
